# Variables:
#   start, end: meeting start/end times in minutes from midnight
#
# Constraints:
#   - Meeting is on Monday.
#   - Meeting must be within work hours: 09:00 to 17:00.
#   - Meeting duration is 30 minutes.
#   - Meeting must not overlap any existing busy interval for Jack or Charlotte.
#   - Preference/constraint: avoid scheduling a new meeting after 12:30,
#     encoded as end_time <= 12:30.
#
# Search:
#   Try feasible start times in chronological order and select the earliest
#   satisfying all constraints.

def to_minutes(time_str):
    hour, minute = time_str.split(":")
    return int(hour) * 60 + int(minute)


def format_time(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


day = "Monday"
work_start = to_minutes("09:00")
work_end = to_minutes("17:00")
duration = 30
preference_limit = to_minutes("12:30")

busy_schedules = {
    "Jack": [
        ("09:30", "10:30"),
        ("11:00", "11:30"),
        ("12:30", "13:00"),
        ("14:00", "14:30"),
        ("16:00", "16:30"),
    ],
    "Charlotte": [
        ("09:30", "10:00"),
        ("10:30", "12:00"),
        ("12:30", "13:30"),
        ("14:00", "16:00"),
    ],
}

busy_intervals = {
    person: [(to_minutes(start), to_minutes(end)) for start, end in intervals]
    for person, intervals in busy_schedules.items()
}


def has_conflict(start, end, intervals):
    for busy_start, busy_end in intervals:
        if start < busy_end and busy_start < end:
            return True
    return False


best_start = None
best_end = None

for start in range(work_start, work_end - duration + 1):
    end = start + duration

    if end > work_end:
        break

    if end > preference_limit:
        continue

    feasible = True
    for intervals in busy_intervals.values():
        if has_conflict(start, end, intervals):
            feasible = False
            break

    if feasible:
        best_start = start
        best_end = end
        break

if best_start is None:
    # Fallback: if the preference is treated as soft, choose the earliest
    # time satisfying only the hard availability constraints.
    for start in range(work_start, work_end - duration + 1):
        end = start + duration

        if end > work_end:
            break

        feasible = True
        for intervals in busy_intervals.values():
            if has_conflict(start, end, intervals):
                feasible = False
                break

        if feasible:
            best_start = start
            best_end = end
            break

print([day, format_time(best_start), format_time(best_end)])

