# Variables:
#   day: one of Monday, Tuesday, Wednesday
#   start: minute-of-day when the 30-minute meeting begins
#
# Constraints:
#   - Meeting must be within 09:00 to 17:00.
#   - Meeting duration is exactly 30 minutes.
#   - Meeting must not overlap any existing busy interval for Amy or Pamela.
#
# Preference constraints from the text are formalized as:
#   - avoid Monday
#   - avoid Tuesday
#   - avoid Wednesday before 16:00
#
# The solver minimizes preference violations and breaks ties by earliest day/time.

DURATION = 30
WORK_START = 9 * 60
WORK_END = 17 * 60
DAYS = ["Monday", "Tuesday", "Wednesday"]

busy = {
    "Amy": {
        "Wednesday": [
            (11 * 60, 11 * 60 + 30),
            (13 * 60 + 30, 14 * 60),
        ]
    },
    "Pamela": {
        "Monday": [
            (9 * 60, 10 * 60 + 30),
            (11 * 60, 16 * 60 + 30),
        ],
        "Tuesday": [
            (9 * 60, 9 * 60 + 30),
            (10 * 60, 17 * 60),
        ],
        "Wednesday": [
            (9 * 60, 9 * 60 + 30),
            (10 * 60, 11 * 60),
            (11 * 60 + 30, 13 * 60 + 30),
            (14 * 60 + 30, 15 * 60),
            (16 * 60, 16 * 60 + 30),
        ],
    },
}

avoidance_rules = [
    ("full_day", "Monday", None),
    ("full_day", "Tuesday", None),
    ("before", "Wednesday", 16 * 60),
]


def is_free(day, start, end):
    for person, day_busy in busy.items():
        for busy_start, busy_end in day_busy.get(day, []):
            if start < busy_end and end > busy_start:
                return False
    return True


def violation_count(day, start):
    count = 0
    for kind, rule_day, threshold in avoidance_rules:
        if kind == "full_day" and day == rule_day:
            count += 1
        elif kind == "before" and day == rule_day and start < threshold:
            count += 1
    return count


def fmt(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


best_key = None
best_result = None

for day in DAYS:
    for start in range(WORK_START, WORK_END - DURATION + 1):
        end = start + DURATION
        if not is_free(day, start, end):
            continue

        key = (violation_count(day, start), DAYS.index(day), start)
        if best_key is None or key < best_key:
            best_key = key
            best_result = (day, start, end)

print([best_result[0], fmt(best_result[1]), fmt(best_result[2])])

