import re

def to_minutes(hhmm):
    h, m = hhmm.split(":")
    return int(h) * 60 + int(m)

def parse_busy(text):
    matches = re.findall(r"(\d{1,2}:\d{2})\s*to\s*(\d{1,2}:\d{2})", text)
    return [(to_minutes(a), to_minutes(b)) for a, b in matches]

def format_time(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

day = "Monday"
day_start = to_minutes("09:00")
day_end = to_minutes("17:00")
duration = 30
avoid_before = to_minutes("14:00")

