    "Victoria": "9:00 to 9:30, 10:30 to 11:30, 13:00 to 14:00, 14:30 to 15:00, 15:30 to 16:30",
    "Thomas": "10:00 to 12:00, 12:30 to 13:00, 14:30 to 16:00",
    "Jennifer": "9:00 to 9:30, 10:00 to 10:30, 11:00 to 13:00, 13:30 to 14:30, 15:00 to 15:30, 16:00 to 16:30",
}

busy = {name: parse_busy(spec) for name, spec in busy_specs.items()}

def is_free(start, end):
    for intervals in busy.values():
        for b_start, b_end in intervals:
            if start < b_end and b_start < end:
                return False
    return True

