def to_minutes(hhmm):
    h, m = hhmm.split(":")
    return int(h) * 60 + int(m)

def to_hhmm(total_minutes):
    return f"{total_minutes // 60:02d}:{total_minutes % 60:02d}"

def parse_intervals(items):
    parsed = []
    for item in items:
        start_text, end_text = item.split(" to ")
        parsed.append((to_minutes(start_text), to_minutes(end_text)))
    return parsed

