# CSP formalization:
# Variables:
#   day   : one of Monday, Tuesday, Wednesday
#   start : meeting start time in minutes from 00:00
#   end   : start + 30 minutes
#
# Hard constraints:
#   1. The meeting must be on the goal day specified in the task: Wednesday.
#   2. The meeting must be within work hours 09:00-17:00.
#   3. The meeting must not overlap any existing busy interval for Joshua or Joyce.
#
# Soft preference:
#   Joyce would rather not meet on Monday before 12:00.
#
# The solver enumerates candidate start times and returns the earliest valid one.

def to_min(hhmm):
    h, m = map(int, hhmm.split(":"))
    return h * 60 + m


def to_str(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


DAYS = ["Monday", "Tuesday", "Wednesday"]
GOAL_DAY = "Wednesday"
WORK_START = to_min("09:00")
WORK_END = to_min("17:00")
MEETING_LENGTH = 30

busy = {
    "Joshua": {
        "Monday": [
            (to_min("15:00"), to_min("15:30")),
        ],
        "Tuesday": [
            (to_min("11:30"), to_min("12:00")),
            (to_min("13:00"), to_min("13:30")),
            (to_min("14:30"), to_min("15:00")),
        ],
        "Wednesday": [],
    },
    "Joyce": {
        "Monday": [
            (to_min("09:00"), to_min("09:30")),
            (to_min("10:00"), to_min("11:00")),
            (to_min("11:30"), to_min("12:30")),
            (to_min("13:00"), to_min("15:00")),
            (to_min("15:30"), to_min("17:00")),
        ],
        "Tuesday": [
            (to_min("09:00"), to_min("17:00")),
        ],
        "Wednesday": [
            (to_min("09:00"), to_min("09:30")),
            (to_min("10:00"), to_min("11:00")),
            (to_min("12:30"), to_min("15:30")),
            (to_min("16:00"), to_min("16:30")),
        ],
    },
}


def overlaps(a_start, a_end, b_start, b_end):
    return a_start < b_end and b_start < a_end


def hard_valid(day, start, end):
    if day != GOAL_DAY:
        return False
    if start < WORK_START or end > WORK_END:
        return False

    for person, day_busy in busy.items():
        for b_start, b_end in day_busy.get(day, []):
            if overlaps(start, end, b_start, b_end):
                return False

    return True


def preference_satisfied(day, start):
    # Joyce would rather not meet on Monday before 12:00.
    return not (day == "Monday" and start < to_min("12:00"))


def solve():
    # Prefer solutions satisfying the stated preference if possible.
    for enforce_preference in (True, False):
        for day in DAYS:
            if day != GOAL_DAY:
                continue

            for start in range(WORK_START, WORK_END - MEETING_LENGTH + 1):
                end = start + MEETING_LENGTH

                if not hard_valid(day, start, end):
                    continue

                if enforce_preference and not preference_satisfied(day, start):
                    continue

                return [day, to_str(start), to_str(end)]

    raise RuntimeError("No valid meeting time found")


if __name__ == "__main__":
    print(solve())

